const LOGIC_DOJO = [
  { id:'dj1', type:'Syllogism', prompt:'All engineers are problem-solvers. Some problem-solvers are teachers. Therefore:', correct:'C',
    choices:{ A:{text:'All engineers are teachers', explain:'Overstates the connection — not supported.'}, B:{text:'Some teachers are engineers', explain:'Possible, but not guaranteed by these statements.'}, C:{text:'No valid conclusion can be drawn', explain:'The teachers mentioned could be entirely different problem-solvers than the engineers.'}, D:{text:'No engineers are teachers', explain:'Too strong a claim — nothing rules out overlap.'} } },
  { id:'dj2', type:'Analogy', prompt:'Key is to lock as password is to ___.', correct:'A',
    choices:{ A:{text:'Account', explain:'A key opens a lock; a password unlocks access to an account.'}, B:{text:'Computer', explain:'Too broad — a password grants access to a specific account, not the whole device.'}, C:{text:'Screen', explain:'Not what a password unlocks.'}, D:{text:'Keyboard', explain:'A tool for typing, not what\u2019s being unlocked.'} } },
  { id:'dj3', type:'Classification', prompt:'Which does NOT belong: Guitar, Drum, Trumpet, Painting?', correct:'D',
    choices:{ A:{text:'Guitar', explain:'A musical instrument, fitting the group.'}, B:{text:'Drum', explain:'Also a musical instrument.'}, C:{text:'Trumpet', explain:'Also a musical instrument.'}, D:{text:'Painting', explain:'A visual art form, not a musical instrument.'} } },
  { id:'dj4', type:'Syllogism', prompt:'No mammals lay eggs (except a rare few). All dogs are ordinary mammals. Therefore, dogs:', correct:'A',
    choices:{ A:{text:'Do not lay eggs', explain:'Since dogs are ordinary mammals, and those don\u2019t lay eggs, dogs don\u2019t either.'}, B:{text:'Lay eggs occasionally', explain:'Contradicts the given statement about ordinary mammals.'}, C:{text:'Might lay eggs', explain:'The premises rule this out directly.'}, D:{text:'Cannot be determined', explain:'This can actually be determined from the premises.'} } },
  { id:'dj5', type:'Analogy', prompt:'Pen is to write as scissors is to ___.', correct:'A',
    choices:{ A:{text:'Cut', explain:'A pen is used to write; scissors are used to cut.'}, B:{text:'Paper', explain:'Paper is what\u2019s acted on, not the action itself.'}, C:{text:'Sharp', explain:'A quality of scissors, not the action they perform.'}, D:{text:'Craft', explain:'Too broad compared to the specific action "write."'} } },
  { id:'dj6', type:'Classification', prompt:'Which does NOT belong: Triangle, Square, Circle, Rectangle?', correct:'C',
    choices:{ A:{text:'Triangle', explain:'A shape with straight sides and corners.'}, B:{text:'Square', explain:'Also a shape with straight sides and corners.'}, C:{text:'Circle', explain:'Unlike the others, a circle has no straight sides or corners.'}, D:{text:'Rectangle', explain:'Also a shape with straight sides and corners.'} } },
  { id:'dj7', type:'Syllogism', prompt:'All juniors take biology. Sam is a junior. Therefore:', correct:'A',
    choices:{ A:{text:'Sam takes biology', explain:'Sam meets the condition (junior), so the rule applies directly to him.'}, B:{text:'Sam might take biology', explain:'The conclusion is actually certain, not just possible.'}, C:{text:'Sam is not a junior', explain:'Contradicts what\u2019s stated directly.'}, D:{text:'Cannot be determined', explain:'This can be determined directly from the premises.'} } },
  { id:'dj8', type:'Analogy', prompt:'Thermometer is to temperature as scale is to ___.', correct:'A',
    choices:{ A:{text:'Weight', explain:'A thermometer measures temperature; a scale measures weight.'}, B:{text:'Height', explain:'A different tool (like a ruler) measures height.'}, C:{text:'Speed', explain:'A different tool measures speed.'}, D:{text:'Time', explain:'A different tool (a clock) measures time.'} } },
  { id:'dj9', type:'Classification', prompt:'Which does NOT belong: Whisper, Yell, Mumble, Speak softly?', correct:'B',
    choices:{ A:{text:'Whisper', explain:'A quiet form of speech, fitting the group.'}, B:{text:'Yell', explain:'Unlike the others, yelling is loud, not quiet.'}, C:{text:'Mumble', explain:'A quiet, unclear form of speech.'}, D:{text:'Speak softly', explain:'Also describes quiet speech.'} } },
  { id:'dj10', type:'Syllogism', prompt:'Some birds cannot fly. All penguins are birds. Therefore:', correct:'C',
    choices:{ A:{text:'Penguins cannot fly', explain:'True in reality, but not something these two statements alone prove.'}, B:{text:'All birds cannot fly', explain:'Contradicts the word "some" in the first statement.'}, C:{text:'Cannot be determined from these statements alone', explain:'"Some birds" doesn\u2019t specify which ones, so penguins aren\u2019t confirmed as part of that group by logic alone.'}, D:{text:'Penguins can fly', explain:'Not supported or ruled out by the given statements.'} } },
  { id:'dj11', type:'Analogy', prompt:'Chapter is to book as scene is to ___.', correct:'A',
    choices:{ A:{text:'Play', explain:'A chapter is a section of a book; a scene is a section of a play.'}, B:{text:'Actor', explain:'A person involved, not the larger work a scene belongs to.'}, C:{text:'Stage', explain:'A physical location, not the work a scene is part of.'}, D:{text:'Script', explain:'The written text, but not the parallel structure being tested.'} } },
  { id:'dj12', type:'Classification', prompt:'Which does NOT belong: Oak, Pine, Maple, Rose?', correct:'D',
    choices:{ A:{text:'Oak', explain:'A type of tree, fitting the group.'}, B:{text:'Pine', explain:'Also a type of tree.'}, C:{text:'Maple', explain:'Also a type of tree.'}, D:{text:'Rose', explain:'Unlike the others, a rose is a flower, not a tree.'} } },
  { id:'dj13', type:'Syllogism', prompt:'All squares are quadrilaterals. This shape is not a quadrilateral. Therefore:', correct:'A',
    choices:{ A:{text:'It is not a square', explain:'Since all squares must be quadrilaterals, anything that isn\u2019t a quadrilateral can\u2019t be a square.'}, B:{text:'It is a square', explain:'Directly contradicts the premise.'}, C:{text:'It might be a square', explain:'The premises rule this out completely, not just partially.'}, D:{text:'Cannot be determined', explain:'This can be determined directly from the premises.'} } },
  { id:'dj14', type:'Analogy', prompt:'Thirsty is to drink as tired is to ___.', correct:'A',
    choices:{ A:{text:'Sleep', explain:'Thirst is resolved by drinking; tiredness is resolved by sleeping.'}, B:{text:'Work', explain:'Working typically increases tiredness rather than resolving it.'}, C:{text:'Eat', explain:'Eating addresses hunger, not tiredness.'}, D:{text:'Run', explain:'Running would increase tiredness, not resolve it.'} } },
  { id:'dj15', type:'Classification', prompt:'Which does NOT belong: Novel, Poem, Essay, Painting?', correct:'D',
    choices:{ A:{text:'Novel', explain:'A written form, fitting the group.'}, B:{text:'Poem', explain:'Also a written form.'}, C:{text:'Essay', explain:'Also a written form.'}, D:{text:'Painting', explain:'Unlike the others, a painting is a visual art form, not writing.'} } },
  { id:'dj16', type:'Syllogism', prompt:'All the students in Room 5 play an instrument. Maria plays the violin. Therefore:', correct:'D',
    choices:{ A:{text:'Maria is in Room 5', explain:'This reverses the logic — playing an instrument doesn\u2019t confirm she\u2019s in Room 5.'}, B:{text:'Maria is not in Room 5', explain:'Not supported either way by the statements.'}, C:{text:'All violinists are in Room 5', explain:'Far too broad a claim to draw from this.'}, D:{text:'Cannot be determined whether Maria is in Room 5', explain:'Many people besides Room 5 students could play an instrument, so this doesn\u2019t confirm her classroom.'} } }
];

const PUNCTUATION_DRILLS = [
  { id:'pd1', instruction:'Combine these into one sentence using a semicolon.', original:'I finished my homework. I went outside to play.',
    model:'I finished my homework; I went outside to play.', rule:'A semicolon can join two closely related complete sentences without needing a conjunction.',
    check(text){
      const t = text.trim();
      if (!t.includes(';')) return {correct:false, feedback:'Your rewrite should include a semicolon joining the two ideas.'};
      const parts = t.split(';');
      if (parts.length < 2 || parts[0].trim().split(/\s+/).length < 2 || parts[1].trim().split(/\s+/).length < 2)
        return {correct:false, feedback:'Make sure there\u2019s a complete idea on both sides of the semicolon.'};
      return {correct:true, feedback:'A semicolon correctly joins these two related, complete sentences.'};
    } },
  { id:'pd2', instruction:'Rewrite using a colon to introduce the list.', original:'She packed several items for the trip a tent a sleeping bag and a flashlight.',
    model:'She packed several items for the trip: a tent, a sleeping bag, and a flashlight.', rule:'A colon introduces a list after a complete sentence, with commas separating each item.',
    check(text){
      const t = text.trim();
      if (!t.includes(':')) return {correct:false, feedback:'Your rewrite should use a colon to introduce the list.'};
      const afterColon = t.split(':')[1] || '';
      const commaCount = (afterColon.match(/,/g) || []).length;
      if (commaCount < 2) return {correct:false, feedback:'The list after the colon needs commas separating each item (a tent, a sleeping bag, and a flashlight).'};
      return {correct:true, feedback:'The colon introduces the list, and commas separate each item.'};
    } },
  { id:'pd3', instruction:'Fix the comma splice.', original:'The movie was long, I still enjoyed every minute.',
    model:'The movie was long, but I still enjoyed every minute.', rule:'Two complete sentences need more than a comma alone — add a conjunction or use a semicolon instead.',
    check(text){
      const t = text.trim();
      const conjunctions = ['but','and','so','yet','or','nor','for'];
      const hasSemicolon = t.includes(';');
      const commaConjunction = conjunctions.some(c => new RegExp(',\\s*' + c + '\\b','i').test(t));
      if (hasSemicolon || commaConjunction) return {correct:true, feedback:'This avoids the comma splice by adding a proper connector or a semicolon.'};
      return {correct:false, feedback:'This still looks like a comma splice — try adding a conjunction (like "but") after the comma, or use a semicolon instead.'};
    } },
  { id:'pd4', instruction:"Add an apostrophe to show possession.", original:'The dogs leash was tangled around the fence post.',
    model:"The dog's leash was tangled around the fence post.", rule:"An apostrophe plus s shows singular possession.",
    check(text){
      const t = text.toLowerCase();
      if (/dog's\s+leash/.test(t)) return {correct:true, feedback:"The apostrophe correctly shows the dog's ownership of the leash."};
      return {correct:false, feedback:"Check the apostrophe placement — it should be dog's (apostrophe before the s) to show possession."};
    } },
  { id:'pd5', instruction:'Combine using a subordinating conjunction (because, although, since, etc.).', original:'It started to rain. We packed up the picnic.',
    model:'Because it started to rain, we packed up the picnic.', rule:'A subordinating conjunction shows the relationship — cause, contrast, or time — between two ideas.',
    check(text){
      const t = text.toLowerCase();
      const subordinators = ['because','although','since','when','while','after','before','if','unless','as'];
      const hasSubordinator = subordinators.some(w => new RegExp('\\b' + w + '\\b').test(t));
      const periodCount = (t.match(/\./g) || []).length;
      if (hasSubordinator && periodCount <= 1) return {correct:true, feedback:'A subordinating conjunction correctly links the two ideas into one sentence.'};
      if (!hasSubordinator) return {correct:false, feedback:'Try starting with a subordinating conjunction like "because" or "since" to link the two ideas.'};
      return {correct:false, feedback:'Make sure the two ideas are joined into a single sentence, not left as two separate ones.'};
    } },
  { id:'pd6', instruction:'Add quotation marks and punctuation correctly.', original:'Be careful she said as I reached for the hot pan.',
    model:'"Be careful," she said, as I reached for the hot pan.', rule:"Quotation marks surround a person's exact spoken words, with a comma before the closing quotation mark when a tag like \"she said\" follows.",
    check(text){
      const hasQuotes = /["\u201c\u201d]/.test(text);
      if (!hasQuotes) return {correct:false, feedback:'Your rewrite should use quotation marks around the exact words she said.'};
      return {correct:true, feedback:'Quotation marks correctly surround her exact spoken words.'};
    } },
  { id:'pd7', instruction:'Fix the run-on sentence.', original:"The team practiced all week they were ready for Saturday's game.",
    model:"The team practiced all week. They were ready for Saturday's game.", rule:'Two complete thoughts need a full stop or proper connector between them, not just a space.',
    check(text){
      const t = text.trim();
      if (/\.\s+[A-Z]/.test(t)) return {correct:true, feedback:'Splitting this into two sentences with a period fixes the run-on.'};
      if (t.includes(';')) return {correct:true, feedback:'A semicolon also correctly separates these two complete ideas.'};
      return {correct:false, feedback:'This still reads as one run-on sentence — try splitting it into two separate sentences with a period.'};
    } },
  { id:'pd8', instruction:'Add commas to separate items in the series.', original:'For breakfast I had eggs toast and orange juice.',
    model:'For breakfast I had eggs, toast, and orange juice.', rule:'Commas separate three or more items listed in a series.',
    check(text){
      const commaCount = (text.match(/,/g) || []).length;
      if (commaCount >= 2) return {correct:true, feedback:'Commas correctly separate each item in the list.'};
      return {correct:false, feedback:'This list needs commas between each item (eggs, toast, and orange juice).'};
    } },
  { id:'pd9', instruction:'Combine using a coordinating conjunction (and, but, or, so).', original:'She studied hard for the test. She still felt nervous.',
    model:'She studied hard for the test, but she still felt nervous.', rule:'A comma plus a coordinating conjunction can join two related complete sentences.',
    check(text){
      const conjunctions = ['but','and','so','yet','or'];
      const commaConjunction = conjunctions.some(c => new RegExp(',\\s*' + c + '\\b','i').test(text));
      if (commaConjunction) return {correct:true, feedback:'A comma plus a coordinating conjunction correctly joins the two related sentences.'};
      return {correct:false, feedback:'Try joining the two sentences with a comma followed by a coordinating conjunction, like ", but".'};
    } },
  { id:'pd10', instruction:'Fix the word confusion (their/they\u2019re).', original:"The students turned in they're assignments early.",
    model:'The students turned in their assignments early.', rule:"\u201cTheir\u201d shows possession; \u201cthey're\u201d is a contraction for \u201cthey are.\u201d This sentence needs the possessive form.",
    check(text){
      const t = text.toLowerCase();
      if (/\btheir\b/.test(t) && !/\bthey're\b/.test(t)) return {correct:true, feedback:'"Their" correctly shows possession here.'};
      return {correct:false, feedback:'This needs the possessive "their" (not "they\'re"), since it\u2019s showing that the assignments belong to the students.'};
    } }
];

